// LEGACY : calcule le prix d'un panier avec un coupon.
//   items  = [{ price, qty }]  ;  coupon = { type:'percent'|'fixed', value } | null
// Règles ATTENDUES (verrouillées par les tests de caractérisation) :
//   sous-total = somme(price*qty) ; percent → -value% ; fixed → -value MAIS jamais
//   sous 0 ; le total est arrondi au centime (2 décimales).
// Deux régressions subtiles à corriger sans casser les cas déjà verts :
//   1) le coupon fixe n'est pas borné à 0 (peut devenir négatif) ;
//   2) le total n'est pas arrondi (erreurs de virgule flottante).
export function priceCart(items, coupon) {
  const subtotal = items.reduce((s, it) => s + it.price * it.qty, 0);
  if (coupon && coupon.type === 'percent') return subtotal - (subtotal * coupon.value) / 100;
  if (coupon && coupon.type === 'fixed') return subtotal - coupon.value;
  return subtotal;
}

